import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Load and apply texture to plane
  const texture = ctx.textureLoader.load(
    config.imageUrl || '/prism-mock/home/nodes/cta-hero-isolated.png'
  );
  texture.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(1, 1);
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
  });

  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position, rotation, and scale
  if (config.scenePosition) {
    const { x = 0, y = 0, z = 0, rotationXYZ, scaleXYZ } = config.scenePosition;
    group.position.set(x, y, z);

    if (rotationXYZ) {
      group.rotation.order = 'XYZ';
      group.rotation.set(rotationXYZ[0] || 0, rotationXYZ[1] || 0, rotationXYZ[2] || 0);
    }

    if (scaleXYZ) {
      group.scale.set(scaleXYZ[0] || 1, scaleXYZ[1] || 1, scaleXYZ[2] || 1);
    }
  }

  // Render text content via MSDF font atlas
  if (config.textContent?.length > 0 && ctx.fontAtlas) {
    const textSpec = config.textContent[0];

    const textMesh = ctx.fontAtlas.createTextMesh({
      text: textSpec.content || '',
      fontSize: textSpec.fontSize || 0.34, // headline size from type scale
      fontFamily: 'display', // Lora serif
      fontWeight: textSpec.fontWeight || 400,
      color: new THREE.Color(config.colors?.ink || '#16161d'),
      anchorX: 'center',
      anchorY: 'middle',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // Cleanup resources
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (texture) texture.dispose();
  };

  // Event handlers (none for static node)
  group.userData.handlers = {};

  return group;
}
